    // =====================================================================
    // UTILS & HELPERS
    // =====================================================================
    function sleep(ms) {
        return new Promise(resolve => setTimeout(resolve, ms));
    }

    function humanDelay(min = 80, max = 180) {
        return sleep(Math.floor(Math.random() * (max - min + 1)) + min);
    }

    async function humanClick(el) {
        if (!el) return;
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        await humanDelay(60, 120);
        const opts = { bubbles: true, cancelable: true, view: window };
        el.dispatchEvent(new MouseEvent('mousedown', opts));
        await humanDelay(20, 50);
        el.dispatchEvent(new MouseEvent('mouseup', opts));
        await humanDelay(15, 35);
        el.dispatchEvent(new MouseEvent('click', opts));
    }

    function setReactInputValue(input, value) {
        if (!input) return;
        input.focus();
        const nativeSetter = Object.getOwnPropertyDescriptor(
            input.tagName === 'TEXTAREA' ? window.HTMLTextAreaElement.prototype : window.HTMLInputElement.prototype,
            'value'
        )?.set;
        if (nativeSetter) {
            nativeSetter.call(input, value);
        } else {
            input.value = value;
        }
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
    }

    async function selectDropdownOption(selectEl, textOrVal) {
        if (!selectEl) return false;
        if (selectEl.tagName === 'SELECT') {
            const target = textOrVal.toLowerCase();
            let matched = false;
            for (let i = 0; i < selectEl.options.length; i++) {
                const opt = selectEl.options[i];
                const optText = (opt.textContent || '').toLowerCase();
                const optVal = (opt.value || '').toLowerCase();
                if (optText.includes(target) || optVal.includes(target)) {
                    selectEl.selectedIndex = i;
                    selectEl.dispatchEvent(new Event('change', { bubbles: true }));
                    matched = true;
                    break;
                }
            }
            return matched;
        } else {
            // Custom dropdown element
            await humanClick(selectEl);
            await humanDelay(100, 200);
            const options = Array.from(document.querySelectorAll('div, li, a, span, button')).filter(el => {
                const t = (el.textContent || '').trim().toLowerCase();
                return t.includes(textOrVal.toLowerCase());
            });
            if (options.length > 0) {
                await humanClick(options[0]);
                return true;
            }
            return false;
        }
    }

